class Solution {
    public int[] numberGame(int[] nums) {
        java.util.Arrays.sort(nums);
        for (int i = 0; i < nums.length; i += 2) {
            int alice = nums[i];
            nums[i] = nums[i + 1];
            nums[i + 1] = alice;
        }
        return nums;
    }
}

class Solution {
    public int[] numberGame(int[] nums) {
        java.util.PriorityQueue<Integer> heap = new java.util.PriorityQueue<>();
        for (int value : nums) {
            heap.offer(value);
        }
        int[] answer = new int[nums.length];
        for (int i = 0; i < answer.length; i += 2) {
            int alice = heap.poll();
            int bob = heap.poll();
            answer[i] = bob;
            answer[i + 1] = alice;
        }
        return answer;
    }
}

class Solution {
    public int[] numberGame(int[] nums) {
        java.util.TreeMap<Integer, Integer> counts = new java.util.TreeMap<>();
        for (int value : nums) {
            counts.put(value, counts.getOrDefault(value, 0) + 1);
        }
        int[] answer = new int[nums.length];
        for (int i = 0; i < answer.length; i += 2) {
            int alice = pollMin(counts);
            int bob = pollMin(counts);
            answer[i] = bob;
            answer[i + 1] = alice;
        }
        return answer;
    }

    private int pollMin(java.util.TreeMap<Integer, Integer> counts) {
        java.util.Map.Entry<Integer, Integer> entry = counts.firstEntry();
        int value = entry.getKey();
        if (entry.getValue() == 1) {
            counts.pollFirstEntry();
        } else {
            counts.put(value, entry.getValue() - 1);
        }
        return value;
    }
}

class Solution {
    public int[] numberGame(int[] nums) {
        int[] answer = new int[nums.length];
        for (int i = 0; i < answer.length; i += 2) {
            int alice = takeMinimum(nums);
            int bob = takeMinimum(nums);
            answer[i] = bob;
            answer[i + 1] = alice;
        }
        return answer;
    }

    private int takeMinimum(int[] nums) {
        int best = 0;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < nums[best]) {
                best = i;
            }
        }
        int value = nums[best];
        nums[best] = Integer.MAX_VALUE;
        return value;
    }
}
